// ... existing code ...
<template>
  <app-layout active-menu="/analytics">
    <div class="analytics-container">
      <div class="analytics-header">
        <h1 class="page-title">数据分析中心</h1>
        <div class="export-actions">
          <el-button
            type="primary"
            icon="el-icon-download"
            @click="exportData('csv')"
            >导出CSV</el-button
          >
          <el-button
            type="success"
            icon="el-icon-document"
            @click="exportData('pdf')"
            >导出PDF</el-button
          >
        </div>
      </div>

      // ... existing code ...
      <!-- 添加顶部统计指标 -->
      <el-row :gutter="20" class="chart-row">
        <el-col :xs="24" :sm="24" :md="12" :lg="8">
          <el-card class="chart-card gauge-card">
            <template #header>
              <div class="chart-header">
                <h3>今日诊断总量</h3>
              </div>
            </template>
            <div ref="revenueGaugeChart" class="gauge-container"></div>
            <div class="gauge-detail">
              <div class="gauge-item">
                <span class="gauge-label">门诊</span>
                <span class="gauge-value">705例</span>
              </div>
              <div class="gauge-item">
                <span class="gauge-label">住院</span>
                <span class="gauge-value">395例</span>
              </div>
            </div>
          </el-card>
        </el-col>
        <el-col :xs="24" :sm="24" :md="12" :lg="8">
          <el-card class="chart-card gauge-card">
            <template #header>
              <div class="chart-header">
                <h3>今日检查人次</h3>
              </div>
            </template>
            <div ref="patientGaugeChart" class="gauge-container"></div>
            <div class="gauge-detail">
              <div class="gauge-item">
                <span class="gauge-label">门诊</span>
                <span class="gauge-value">280人</span>
              </div>
              <div class="gauge-item">
                <span class="gauge-label">住院</span>
                <span class="gauge-value">160人</span>
              </div>
            </div>
          </el-card>
        </el-col>
        <el-col :xs="24" :sm="24" :md="12" :lg="8">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>患者流量及调阅量</h3>
              </div>
            </template>
            <div ref="patientFlowChart" class="gauge-container"></div>
            <div class="stat-badges">
              <div class="stat-badge">
                <span class="stat-num">79</span>
                <span class="stat-label">活跃病历数</span>
              </div>
              <div class="stat-badge">
                <span class="stat-num">81</span>
                <span class="stat-label">上传病例数</span>
              </div>
            </div>
          </el-card>
        </el-col>
      </el-row>

      <el-row :gutter="20" class="chart-row">
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>门诊人次变化趋势</h3>
              </div>
            </template>
            <div ref="visitTrendChart" class="chart-container"></div>
          </el-card>
        </el-col>
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>平均等待/诊疗时间</h3>
              </div>
            </template>
            <div ref="waitingTimeChart" class="chart-container"></div>
          </el-card>
        </el-col>
      </el-row>

      <!-- 眼科疾病分布图表 -->
      <el-row :gutter="20" class="chart-row">
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>疾病分布分析</h3>
              </div>
            </template>
            <div ref="diseaseDistributionChart" class="chart-container"></div>
          </el-card>
        </el-col>
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>AI诊断准确率分析</h3>
              </div>
            </template>
            <div ref="accuracyChart" class="chart-container"></div>
          </el-card>
        </el-col>
      </el-row>

      <!-- 患者数据分析 -->
      <el-row :gutter="20" class="chart-row">
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>患者年龄分布</h3>
              </div>
            </template>
            <div ref="ageDistributionChart" class="chart-container"></div>
          </el-card>
        </el-col>
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>患者性别分布</h3>
              </div>
            </template>
            <div ref="genderDistributionChart" class="chart-container"></div>
          </el-card>
        </el-col>
      </el-row>

      <!-- 诊断TOP数据 -->
      <el-row :gutter="20" class="chart-row">
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>门诊收入TOP5</h3>
              </div>
            </template>
            <div ref="deptRevenueChart" class="chart-container"></div>
          </el-card>
        </el-col>
        <el-col :xs="24" :sm="24" :md="12" :lg="12">
          <el-card class="chart-card">
            <template #header>
              <div class="chart-header">
                <h3>健康人次TOP5</h3>
              </div>
            </template>
            <div ref="deptVisitChart" class="chart-container"></div>
          </el-card>
        </el-col>
      </el-row>

      <el-card class="progress-card">
        <el-row :gutter="20">
          <el-col :xs="24" :sm="12" :md="6" :lg="6">
            <div class="progress-item">
              <h4>门诊占比</h4>
              <div ref="outpatientProgress" class="progress-chart"></div>
